        kRobotoCondensedBodyAscent + kRobotoCondensedBodyDescent +
        kLineGap + kRobotoCondensedMetaAscent + kRobotoCondensedMetaDescent;
    return static_cast<std::int16_t>(
        bounds.y + (bounds.height - kTextBlockHeight) / 2);
