void renderRssiHistory(const ObservationHistory& history) {
    if (!history.valid || history.retainedSamples == 0) return;
    char line[64] = {};
    std::snprintf(line, sizeof(line), tr(UiTextId::SignalRangeFormat),
                  static_cast<int>(history.minimumRssiDbm),
                  static_cast<int>(history.maximumRssiDbm));
    display.setTextColor(Palette::Positive, Palette::Canvas);
    setUiCursor(UiTextRole::Meta, 14, 199);
    display.print(line);

    constexpr std::int16_t x = 136;
    constexpr std::int16_t y = 187;
    constexpr std::int16_t width = 90;
    constexpr std::int16_t height = 35;
    display.drawRoundRect(x, y, width, height, Layout::Radius, Palette::Divider);
    const auto pointY = [&](std::int16_t rssi) {
        const std::int16_t bounded = rssi < -100 ? -100 : (rssi > -20 ? -20 : rssi);
        return static_cast<std::int16_t>(
            y + height - 3 - ((bounded + 100) * (height - 6)) / 80);
    };
    if (history.retainedSamples == 1) {
        display.fillCircle(x + width / 2, pointY(history.samples[0]), 2,
                           Palette::Focus);
        return;
    }
    for (std::uint8_t index = 1; index < history.retainedSamples; ++index) {
        const std::int16_t previousX = static_cast<std::int16_t>(
            x + 3 + ((index - 1U) * (width - 6)) /
                        (history.retainedSamples - 1U));
        const std::int16_t currentX = static_cast<std::int16_t>(
            x + 3 + (index * (width - 6)) /
                        (history.retainedSamples - 1U));
        display.drawLine(previousX, pointY(history.samples[index - 1U]),
                         currentX, pointY(history.samples[index]),
                         Palette::Focus);
    }
}

UiTextId surveySourceLabel(const SurveySourceOption& source) {
    return source.kind == SurveySourceKind::Wifi
        ? UiTextId::SourceWifiRow : UiTextId::SourceBleRow;
}

UiTextId surveySourceNote(const SurveySourceOption& source) {
    if (source.state == SurveySourceState::Available) {
        return source.selected ? UiTextId::SourceOnReady
                               : UiTextId::SourceOffReady;
    }
    if (source.state == SurveySourceState::Conflicted) {
        return UiTextId::SourceConflicted;
    }
    if (source.state == SurveySourceState::Fault) {
        return UiTextId::SourceFault;
    }
    return UiTextId::SourceDriverPending;
}

Rect surveyPlanRowBounds(std::uint8_t index) {
    return Components::choiceRow(index);
}

void renderSurveyPlanRow(std::uint8_t index) {
    if (index >= surveySourceController.planItemCount()) return;
    char note[48] = {};
    const bool selected = surveySourceController.selection() == index;
    if (surveySourceController.scope() != SurveySourceScope::All) {
        const bool wifi = surveySourceController.scope() ==
                          SurveySourceScope::WifiOnly;
        const bool ready = surveySourceController.canStart();
        renderMenuRow(surveyPlanRowBounds(index),
                      tr(wifi ? UiTextId::WifiScanStart
                              : UiTextId::BleScanStart),
                      tr(ready ? UiTextId::StartReady
                               : UiTextId::StartNeedsSource),
                      selected, ready,
                      ready ? Tone::Positive : Tone::Warning);
        return;
    }
    if (index == 0) {
        if (surveySourceController.simulatedPreview() &&
            surveySourceController.selectedCount() == 0) {
            std::snprintf(note, sizeof(note), "%s", tr(UiTextId::SourcesPreview));
        } else {
            std::snprintf(note, sizeof(note), tr(UiTextId::SourcesCountFormat),
                          static_cast<unsigned>(
                              surveySourceController.selectedCount()),
                          static_cast<unsigned>(
                              SurveySourceController::kSourceCount));
        }
        renderMenuRow(surveyPlanRowBounds(index), tr(UiTextId::PlanSources),
                      note, selected, true, Tone::Positive);
        return;
    }
    if (index == 1) {
        const bool available = BoardProfile::kRfShieldDeclared &&
            !BoardProfile::kGpsDeclared && !BoardProfile::kPn532Declared;
        renderMenuRow(surveyPlanRowBounds(index), tr(UiTextId::PlanSpectrum),
                      tr(available ? UiTextId::SpectrumReady
                                   : UiTextId::SpectrumUnavailable),
                      selected, available,
                      available ? Tone::Positive : Tone::Warning);
        return;
    }
    const bool preparing =
        std::strcmp(productSurveyRuntime.status, "preparing") == 0;
    const bool cancelling =
        std::strcmp(productSurveyRuntime.status, "cancelling") == 0;
    const bool ready = surveySourceController.canStart() &&
                       !preparing && !cancelling;
    const UiTextId startNote = preparing
        ? UiTextId::StartPreparing
        : (cancelling
               ? UiTextId::StartCancelling
               : (!ready
                      ? UiTextId::StartNeedsSource
                      : (surveySourceController.simulatedPreview()
                             ? UiTextId::StartPreview
                             : UiTextId::StartReady)));
    renderMenuRow(surveyPlanRowBounds(index), tr(UiTextId::PlanStart),
                  tr(startNote), selected, ready,
                  ready ? Tone::Positive : Tone::Warning);
}

void renderSurveySourceRow(std::uint8_t index) {
    const SurveySourceOption* source = surveySourceController.get(index);
    if (source == nullptr) return;
    const bool selected = surveySourceController.selection() == index;
    renderMenuRow(Components::choiceRow(index), tr(surveySourceLabel(*source)),
                  tr(surveySourceNote(*source)), selected,
                  source->available(),
                  source->selected ? Tone::Positive : Tone::Muted);
}

constexpr std::uint8_t kWifiProductTaskCount = 5;

UiTextId wifiProductLabel(std::uint8_t index) {
    constexpr UiTextId labels[kWifiProductTaskCount] = {
        UiTextId::WifiMenuNetworks,
        UiTextId::WifiMenuDevices,
        UiTextId::WifiMenuChannels,
        UiTextId::WifiMenuVisit,
        UiTextId::WifiMenuAirspaceGuard,
    };
    return labels[index < kWifiProductTaskCount ? index : 0];
}

UiTextId wifiProductNote(std::uint8_t index) {
    constexpr UiTextId notes[kWifiProductTaskCount] = {
        UiTextId::WifiMenuNetworksNote,
        UiTextId::WifiMenuDevicesNote,
        UiTextId::WifiMenuChannelsNote,
        UiTextId::WifiMenuVisitNote,
        UiTextId::WifiMenuAirspaceGuardNote,
    };
    return notes[index < kWifiProductTaskCount ? index : 0];
}

bool wifiProductTaskReady(std::uint8_t index) {
    // Functions are admitted one at a time. The menu stays truthful while the
    // remaining radio workflows are being implemented and measured.
    return index < kWifiProductTaskCount;
}

std::uint8_t wifiProductFirstVisible(std::uint8_t selection) {
    return homeFirstVisible(selection);
}

void renderWifiProductRow(std::uint8_t index, std::uint8_t firstVisible) {
    if (index >= kWifiProductTaskCount || index < firstVisible ||
        index >= firstVisible + kVisibleHomeRows) return;
    const bool ready = wifiProductTaskReady(index);
    renderMenuRow(Components::homeRow(index - firstVisible),
                  tr(wifiProductLabel(index)),
                  tr(ready ? wifiProductNote(index) : UiTextId::WifiMenuNext),
                  wifiProductSelection == index, ready,
                  ready ? Tone::Positive : Tone::Muted);
}

void renderWifiProductMenu(bool clearContent) {
    renderHeader(tr(UiTextId::WifiMenuTitle), clearContent);
    const std::uint8_t first = wifiProductFirstVisible(wifiProductSelection);
    const std::uint8_t end = static_cast<std::uint8_t>(
        std::min<std::size_t>(kWifiProductTaskCount,
                              first + kVisibleHomeRows));
    for (std::uint8_t index = first; index < end; ++index) {
        renderWifiProductRow(index, first);
    }
}

Tone airspaceGuardTone(AirspaceGuardUiTone tone) {
    switch (tone) {
        case AirspaceGuardUiTone::Healthy: return Tone::Positive;
        case AirspaceGuardUiTone::Caution: return Tone::Warning;
        case AirspaceGuardUiTone::Finding:
        case AirspaceGuardUiTone::Error: return Tone::Danger;
        case AirspaceGuardUiTone::Neutral:
        default: return Tone::Neutral;
    }
}

Rect airspaceGuardRowBounds(std::uint8_t row) {
    constexpr std::int16_t kTop = 88;
    constexpr std::int16_t kHeight = 44;
    constexpr std::int16_t kGap = 5;
    return {Layout::Edge,
            static_cast<std::int16_t>(kTop + row * (kHeight + kGap)),
            Layout::ContentWidth, kHeight};
}

void renderAirspaceGuardRow(const AirspaceGuardUiModel& model,
                            std::uint8_t row) {
    const Rect bounds = airspaceGuardRowBounds(row);
    const bool visible = row < model.rowCount;
    if (!visible) {
        display.fillRect(bounds.x, bounds.y, bounds.width, bounds.height,
                         Palette::Canvas);
        return;
    }
    const bool selected = visible && model.rows[row].selected;
    const std::uint16_t background = selected ? Palette::SurfaceFocus
                                              : Palette::Surface;
    display.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height,
                          Layout::Radius, background);
    renderFocusCue(bounds, selected);
    display.setTextColor(selected ? Palette::Focus : Palette::TextSecondary,
                         background);
    const std::int16_t top = static_cast<std::int16_t>(
        bounds.y + (bounds.height - kRobotoCondensedBodyAscent -
                    kRobotoCondensedBodyDescent) / 2);
    setUiCursor(UiTextRole::Body, bounds.x + kInteractiveRowTextInset, top);
    display.print(model.rows[row].text.data());
}

void renderAirspaceGuardPage(bool clearContent, bool liveDataOnly = false) {
    AirspaceGuardUiModel model{};
    if (airspaceGuardCaptureState ==
        AirspaceGuardCaptureState::WifiRunning) {
        model.headline = UiTextId::AirspaceGuardListening;
        model.note = UiTextId::AirspaceGuardPassiveOnly;
        model.tone = AirspaceGuardUiTone::Neutral;
        const auto capture = wifiFrameCapture.stats();
        const auto monitor = wifiFrameCapture.airspaceGuardMonitorStats();
        const std::uint64_t nowUs = static_cast<std::uint64_t>(
            esp_timer_get_time());
        const std::uint64_t deadlineUs = capture.startedUs +
            static_cast<std::uint64_t>(kAirspaceGuardCaptureDurationMs) *
                1000ULL;
        const std::uint64_t remainingTenths = nowUs < deadlineUs
            ? (deadlineUs - nowUs + 99999ULL) / 100000ULL : 0U;
        std::snprintf(model.context.data(), model.context.size(),
                      tr(UiTextId::AirspaceGuardChannelFormat),
                      static_cast<unsigned>(wifiFrameCapture.currentChannel()));
        std::snprintf(model.rows[0].text.data(), model.rows[0].text.size(),
                      tr(UiTextId::AirspaceGuardTimeFormat),
                      static_cast<unsigned>(remainingTenths / 10U),
                      static_cast<unsigned>(remainingTenths % 10U));
        std::snprintf(model.rows[1].text.data(), model.rows[1].text.size(),
                      tr(UiTextId::AirspaceGuardSeenFormat),
                      static_cast<unsigned long>(monitor.framesReported));
        std::snprintf(
            model.rows[2].text.data(), model.rows[2].text.size(),
            tr(UiTextId::AirspaceGuardEvidenceKindsFormat),
            static_cast<unsigned long>(monitor.disconnectFramesRetained),
            static_cast<unsigned long>(monitor.identityProfilesRetained));
        std::snprintf(model.rows[3].text.data(), model.rows[3].text.size(),
                      tr(UiTextId::AirspaceGuardRetainedFormat),
                      static_cast<unsigned long>(monitor.framesRetained));
        model.rowCount = model.rows.size();
    } else if (airspaceGuardCaptureState ==
               AirspaceGuardCaptureState::BleRunning) {
        model.headline = UiTextId::AirspaceGuardBleListening;
        model.note = UiTextId::AirspaceGuardPassiveOnly;
        model.tone = AirspaceGuardUiTone::Neutral;
        const std::uint64_t nowUs = static_cast<std::uint64_t>(
            esp_timer_get_time());
        const std::uint64_t deadlineUs = airspaceGuardBleStartedUs +
            static_cast<std::uint64_t>(kAirspaceGuardCaptureDurationMs) *
                1000ULL;
        const std::uint64_t remainingTenths = nowUs < deadlineUs
            ? (deadlineUs - nowUs + 99999ULL) / 100000ULL : 0U;
        std::snprintf(model.context.data(), model.context.size(),
                      tr(UiTextId::AirspaceGuardStageFormat), 2U);
        std::snprintf(model.rows[0].text.data(), model.rows[0].text.size(),
                      tr(UiTextId::AirspaceGuardTimeFormat),
                      static_cast<unsigned>(remainingTenths / 10U),
                      static_cast<unsigned>(remainingTenths % 10U));
        std::snprintf(model.rows[1].text.data(), model.rows[1].text.size(),
                      "%s", tr(UiTextId::AirspaceGuardBlePurpose));
        std::snprintf(model.rows[2].text.data(), model.rows[2].text.size(),
                      "%s", tr(UiTextId::AirspaceGuardBleNoConnection));
        std::snprintf(model.rows[3].text.data(), model.rows[3].text.size(),
                      "%s", tr(UiTextId::AirspaceGuardResultAfterCleanup));
        model.rowCount = model.rows.size();
    } else {
        model = leshy1::ui::presentAirspaceGuard(
            airspaceGuardController, languageController.active());
        if (airspaceGuardCaptureState == AirspaceGuardCaptureState::Failed) {
            std::snprintf(model.context.data(), model.context.size(), "%s",
                          tr(UiTextId::AirspaceGuardCaptureFailed));
        }
    }
    if (airspaceGuardResultNeedsContentClear) {
        display.fillRect(Layout::Edge, Layout::ContentTop,
                         Layout::ContentWidth,
                         Layout::FooterDividerY - Layout::ContentTop,
                         Palette::Canvas);
        airspaceGuardResultNeedsContentClear = false;
    }
    if (!liveDataOnly) {
        renderHeader(tr(model.title), clearContent);
        display.fillRect(Layout::Edge, 28, Layout::ContentWidth, 56,
                         Palette::Canvas);
        display.setTextColor(toneColor(airspaceGuardTone(model.tone)),
                             Palette::Canvas);
        setUiCursor(UiTextRole::Body, Layout::Edge, 32);
        display.print(tr(model.headline));
        display.setTextColor(model.evidenceIncomplete ? Palette::Warning
                                                      : Palette::TextMuted,
                             Palette::Canvas);
        setUiCursor(UiTextRole::Meta, Layout::Edge, 54);
        display.print(tr(model.note));
    } else if (airspaceGuardCaptureState !=
               AirspaceGuardCaptureState::BleRunning) {
        // Live cadence repaints only the changing channel/counters. Header,
        // headline, passive note and footer remain untouched and cannot flash.
        display.fillRect(Layout::Edge, 67, Layout::ContentWidth, 17,
                         Palette::Canvas);
    }
    if (!liveDataOnly || airspaceGuardCaptureState !=
            AirspaceGuardCaptureState::BleRunning) {
        display.setTextColor(Palette::TextSecondary, Palette::Canvas);
        setUiCursor(UiTextRole::Meta, Layout::Edge, 70);
        display.print(model.context.data());
    }
    const std::uint8_t rowsToRender =
        liveDataOnly && airspaceGuardCaptureState ==
                            AirspaceGuardCaptureState::BleRunning
            ? 1U
            : AirspaceGuardUiModel::kVisibleRowCapacity;
    for (std::uint8_t row = 0; row < rowsToRender; ++row) {
        renderAirspaceGuardRow(model, row);
    }
}

